// Theme switch: chart must be recreated (not duplicated) and recolored.
await page.emulateMedia({ colorScheme: 'dark' });
await page.waitForTimeout(1500);
const dark = await page.evaluate(() => ({
  panelTheme: document.querySelector('.cpu-panel').dataset.theme,
  uplotCount: document.querySelectorAll('.uplot').length,
  yagrClasses: document.querySelector('.cpu-chart').className,
}));
