await page.screenshot({ path: '/tmp/browsercheck/dark.png' });

// Unmount: navigating away should not leave timers or charts behind.
const hasTimersLeft = await page.evaluate(() => new Promise((res) => setTimeout(() => res('ok'), 10)));
console.log('LOGS', JSON.stringify(logs, null, 1));
await browser.close();
EOF
