await ctx.addInitScript(() => {
  Object.defineProperty(Navigator.prototype, 'language', { get: () => 'en-US' });
  Object.defineProperty(Navigator.prototype, 'languages', { get: () => ['en-US'] });
  // Считаем живые таймеры и ResizeObserver, чтобы проверить освобождение ресурсов.
  const live = new Set();
  const si = window.setInterval, ci = window.clearInterval;
  window.setInterval = (...a) => { const id = si(...a); live.add(id); return id; };
  window.clearInterval = (id) => { live.delete(id); return ci(id); };
  window.__liveIntervals = () => live.size;
  let roLive = 0;
  const RO = window.ResizeObserver;
  window.ResizeObserver = class extends RO {
    constructor(cb) { super(cb); this.__observed = new Set(); }
    observe(el, o) { roLive++; this.__observed.add(el); return super.observe(el, o); }
    unobserve(el) { if (this.__observed.delete(el)) roLive--; return super.unobserve(el); }
    disconnect() { roLive -= this.__observed.size; this.__observed.clear(); return super.disconnect(); }
  };
  window.__liveRO = () => roLive;
  window.__longTasks = [];
